cases.fixed:
fun bucketSort(values: List<Int>, bucketCount: Int): List<Int> {
    val frequencies = IntArray(bucketCount)
    values.forEach { frequencies[it] += 1 }
    return frequencies.indices.flatMap { bucket -> List(frequencies[bucket]) { bucket } }
}

